contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that exercises approval and a log call
    function run(address logger, address keepAddr) public payable {
        require(logger != address(0));
        // initially the provided logger should not be approved (public getter)
        bool initiallyApproved = c.approvedToLog(logger);

        // Ensure initial is false for a freshly deployed c would normally be false,
        // but we don't require it; we will observe behavior changes after toggling.

        // From this contract, call setApprovedLogger to set logger -> true
        // The InvMutTest contract is the caller of c functions; we must use `logger` as the target
        // for the approval mapping, but msg.sender of subsequent log calls will be this contract
        // so we will try approving address(this) as logger to be able to log successfully.

        // Approve this contract as logger
        c.setApprovedLogger(address(this), true);

        // Now approvedToLog for this contract should be true
        bool approvedAfterSet = c.approvedToLog(address(this));

        // Call a log function that returns bool; capture whether it reverted
        bool reverted = false;
        bool ret = false;
        try c.logCreated(keepAddr) returns (bool r) {
            ret = r;
        } catch {
            reverted = true;
        }

        // Now reset approval to false
        c.setApprovedLogger(address(this), false);
        bool approvedAfterClear = c.approvedToLog(address(this));

        // Call the same log function again and capture result/revert
        bool reverted2 = false;
        bool ret2 = false;
        try c.logCreated(keepAddr) returns (bool r2) {
            ret2 = r2;
        } catch {
            reverted2 = true;
        }

        // General property to assert:
        // - Setting approved logger to true makes approvedToLog return true and a subsequent log call must NOT revert and must return true.
        // - Clearing approval makes approvedToLog return false and a subsequent log call must NOT revert and must return false.
        // We assert this relation between the observable getters and the boolean returns/reverts.
        assert(
            approvedAfterSet == true
            && reverted == false
            && ret == true
            && approvedAfterClear == false
            && reverted2 == false
            && ret2 == false
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check.
    // params:
    //   target: the address to be approved/unapproved in the mapping
    //   keepAddr: argument passed to logCreated
    function run(address target, address keepAddr) public payable {
        require(target != address(0));

        // First, set approval to the boolean value 'true'
        c.setApprovedLogger(target, true);
        // Read public getter to observe effect
        bool afterSetTrue = c.approvedToLog(target);

        // Call logCreated from this contract (msg.sender == address(this)); 
        // only relevant if target == address(this) because msg.sender matters for logCreated.
        // We will also check behavior when target is this contract by toggling approval for address(this).
        // Approve this test contract explicitly so that a log call from this contract can succeed.
        c.setApprovedLogger(address(this), true);
        bool approvedThisTrue = c.approvedToLog(address(this));

        bool revertedTrue = false;
        bool retTrue = false;
        try c.logCreated(keepAddr) returns (bool r) {
            retTrue = r;
        } catch {
            revertedTrue = true;
        }

        // Now set approval to false for both addresses
        c.setApprovedLogger(target, false);
        bool afterSetFalse = c.approvedToLog(target);

        c.setApprovedLogger(address(this), false);
        bool approvedThisFalse = c.approvedToLog(address(this));

        bool revertedFalse = false;
        bool retFalse = false;
        try c.logCreated(keepAddr) returns (bool r2) {
            retFalse = r2;
        } catch {
            revertedFalse = true;
        }

        // General rule asserted:
        // - The approvedToLog getter reflects the last value set for any address (we observed for `target`)
        // - For this contract (the actual caller), when approvedToLog(address(this)) is true a log call must NOT revert and must return true;
        //   when it's false a log call must NOT revert and must return false.
        // We express this as a single assert relating the observed booleans.
        assert(
            // mapping reflects last set for arbitrary target
            afterSetTrue == true
            && afterSetFalse == false
            // and for this caller, the return/revert behavior matches the approval boolean
            && approvedThisTrue == true
            && revertedTrue == false
            && retTrue == true
            && approvedThisFalse == false
            && revertedFalse == false
            && retFalse == false
        );
    }

    receive() external payable {}
}

