        try c.logSetupFailed() returns (bool r) { r5Ret = r; } catch { r5Reverted = true; }

        bool r6Reverted = false; bool r6Ret = false;
        try c.logFraudDuringSetup() returns (bool r) { r6Ret = r; } catch { r6Reverted = true; }

        bool r7Reverted = false; bool r7Ret = false;
        try c.logFunded() returns (bool r) { r7Ret = r; } catch { r7Reverted = true; }

