            && r8Reverted == false && r8Ret == observedApprovalThis
            && r9Reverted == false && r9Ret == observedApprovalThis
            && r10Reverted == false && r10Ret == observedApprovalThis
            && r11Reverted == false && r11Ret == observedApprovalThis
