contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address loggerToToggle, address otherAddr, bytes32 b1, bytes32 b2, bytes32 b3) public payable {
        require(loggerToToggle != address(0) && otherAddr != address(0));

        // Record initial approval statuses via public getter
        bool before_logger = c.approvedToLog(loggerToToggle);
        bool before_other = c.approvedToLog(otherAddr);

        // Try to call various logging methods as this contract (msg.sender == address(this))
        // First ensure this contract is not mistakenly approved: if it is, flip it off using onlyOwner cannot be called here
        // We cannot call setApprovedLogger because onlyOwner restricts it and InvMutTest is not owner of c.
        // So we proceed with current msg.sender approval status = c.approvedToLog(address(this))
        bool meApproved = c.approvedToLog(address(this));

        // Attempt several log calls that should return false if not approved, true if approved.
        bool r1 = c.logCreated(otherAddr);
        bool r2 = c.logGotRedemptionSignature(b1, b2, b3);
        bool r3 = c.logRegisteredPubkey(b1, b2);
        bool r4 = c.logSetupFailed();
        bool r5 = c.logRedemptionRequested(otherAddr, b1, 1, abi.encodePacked(uint8(0x01)), 0, abi.encodePacked(uint8(0x02)));
        bool r6 = c.logFunded();
        bool r7 = c.logCourtesyCalled();
        bool r8 = c.logStartedLiquidation(true);
        bool r9 = c.logRedeemed(b1);
        bool r10 = c.logLiquidated();
        bool r11 = c.logExitedCourtesyCall();
        bool r12 = c.logFraudDuringSetup();

        // After making logging calls, assert that approvedLoggers mapping did not change for observed addresses
        bool after_logger = c.approvedToLog(loggerToToggle);
        bool after_other = c.approvedToLog(otherAddr);

        // General rule: none of these logging calls change approval status of arbitrary addresses;
        // additionally, each call's boolean result must equal whether this contract was approved at call time.
        assert(
            after_logger == before_logger
            && after_other == before_other
            && r1 == meApproved
            && r2 == meApproved
            && r3 == meApproved
            && r4 == meApproved
            && r5 == meApproved
            && r6 == meApproved
            && r7 == meApproved
            && r8 == meApproved
            && r9 == meApproved
            && r10 == meApproved
            && r11 == meApproved
            && r12 == meApproved
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address ownerCandidate;
    constructor(C _c) { c = _c; ownerCandidate = address(0x12345); }

    // single public test function taking parameters
    function run(address target, bool newStatus) public payable {
        require(target != address(0), "avoid zero address to keep expressiveness");

        // Read the approval status before the call through public getter
        bool before = c.approvedLoggers(target);

        // Attempt the state-changing call: onlyOwner modifier will allow only contract owner
        bool reverted;
        try c.setApprovedLogger(target, newStatus) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the approval status after the call
        bool after = c.approvedLoggers(target);

        // General rule: if the call reverted then mapping must be unchanged; if it didn't revert
        // then mapping must equal newStatus. This captures that only an allowed caller (owner)
        // can change that mapping and successful call sets the value to the provided status.
        assert(reverted ? (after == before) : (after == newStatus));
    }

    // allow receiving Ether if needed by future variations
    receive() external payable { }
}

