contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We choose one representative logging function that returns bool: logFunded
    // The test will: record approvedLoggers for this contract, attempt to call logFunded,
    // catch whether it reverted, read the return value when possible, and finally assert
    // that whatever happened, the approvedLoggers mapping for this caller is unchanged and
    // that a true return implies approvedLoggers was true before, while a false return
    // implies approvedLoggers was false before.
    function run() public payable {
        // no parameter preconditions
        // read approval status before
        bool before = c.approvedLoggers(address(this));

        // attempt the call, capture whether it reverted and the return value if any
        bool reverted = false;
        bool returnedValue = false;
        try c.logFunded() returns (bool r) {
            returnedValue = r;
        } catch {
            reverted = true;
        }

        // read approval status after
        bool after = c.approvedLoggers(address(this));

        // General rule (single assert):
        // - The call must not change the caller's approvedLoggers entry (after == before)
        // - If the call returned true then before must have been true (since only approved callers should get true)
        // - If the call returned false then before must have been false
        // Note: if the call reverted, we only require mapping unchanged.
        assert(after == before && (reverted || ((returnedValue && before) || (!returnedValue && !before))));
    }

    receive() external payable { }
}

